#include "xavrx/memory/memory.hpp"
#include <cstdint>
#include <iostream>
namespace { int failures=0;void check(bool ok,const char* m){if(!ok){std::cerr<<"FAIL: "<<m<<'\n';++failures;}}
class Device final:public xavrx::memory::MemoryMappedDevice{public:bool read(std::uint32_t o,std::uint8_t w,std::uint64_t& v)noexcept override{if(fail||o+w>8U)return false;v=value;offset=o;width=w;return true;}bool write(std::uint32_t o,std::uint8_t w,std::uint64_t v)noexcept override{if(fail||o+w>8U)return false;value=v;offset=o;width=w;return true;}std::uint64_t value{0x1122334455667788ULL};std::uint32_t offset{};std::uint8_t width{};bool fail{};};}
int main(){using namespace xavrx::memory;Memory m(0x1000U,0x1000U);check(m.valid()&&m.ram_size()==0x1000U,"RAM configuration");
 check(m.write8(0x1000U,0xABU)==AccessResult::Success,"write8");check(m.write16(0x1002U,0xCDEFU)==AccessResult::Success,"write16");check(m.write32(0x1004U,0x12345678U)==AccessResult::Success,"write32");check(m.write64(0x1008U,0x0123456789ABCDEFULL)==AccessResult::Success,"write64");
 std::uint8_t b=0;std::uint16_t h=0;std::uint32_t w=0;std::uint64_t d=0;check(m.read8(0x1000U,b)==AccessResult::Success&&b==0xABU,"read8");check(m.read16(0x1002U,h)==AccessResult::Success&&h==0xCDEFU,"read16");check(m.read32(0x1004U,w)==AccessResult::Success&&w==0x12345678U,"read32");check(m.read64(0x1008U,d)==AccessResult::Success&&d==0x0123456789ABCDEFULL,"read64");check(m.read32(0x1004U,w)==AccessResult::Success&&w==0x12345678U,"big endian");
 check(m.read32(0x1001U,w)==AccessResult::Misaligned,"misaligned read");check(m.write64(0x1004U,0)==AccessResult::Misaligned,"misaligned write");check(m.read32(0x1FFEU,w)==AccessResult::Unmapped,"cross-boundary read");check(m.read8(0x3000U,b)==AccessResult::Unmapped,"unmapped address");check(m.read(0x1000U,3U,d)==AccessResult::InvalidWidth,"invalid width");
 Device dev;check(m.map_device(0xCC000000U,8U,dev),"MMIO mapping");check(!m.map_device(0xCC000004U,8U,dev),"overlapping MMIO rejected");check(!m.map_device(0x1000U,8U,dev),"RAM overlap rejected");check(m.write32(0xCC000000U,0xAABBCCDDU)==AccessResult::Success&&dev.value==0xAABBCCDDU&&dev.width==4U,"MMIO write dispatch");check(m.read32(0xCC000000U,w)==AccessResult::Success&&w==0xAABBCCDDU&&dev.offset==0U,"MMIO read dispatch");dev.fail=true;auto old=w;check(m.read32(0xCC000000U,w)==AccessResult::DeviceError&&w==old,"device read error preserves output");check(m.write32(0xCC000000U,1U)==AccessResult::DeviceError,"device write error");
 Memory invalid(0xFFFFFFF0U,0x100U);check(!invalid.valid()&&invalid.read8(0U,b)==AccessResult::InvalidConfiguration,"invalid address range");Memory edge(0xFFFFFFF0U,0x10U);check(edge.valid()&&edge.write32(0xFFFFFFFCU,0xCAFEBABEU)==AccessResult::Success,"top address range");check(!edge.map_device(0xFFFFFFF0U,0x10U,dev),"device cannot overlap RAM");Memory empty(0U,0U);check(!empty.valid(),"zero-sized RAM rejected");
 if(failures){std::cerr<<failures<<" memory tests failed\n";return 1;}std::cout<<"All XAVRX-WII memory subsystem tests passed\n";return 0;}
